// The rules site: renders window.HEARTY (rules.js, generated by tests/docs.rs from hearty's
// code and output) and makes it searchable and filterable. No dependencies, no build step.
(function () {
  "use strict";

  const DATA = window.HEARTY;
  const root = document.documentElement;
  const $ = (selector) => document.querySelector(selector);

  /* ---- Theme ------------------------------------------------------------------------ */

  const darkQuery = window.matchMedia("(prefers-color-scheme: dark)");
  const themeButton = $("#theme-toggle");

  function effectiveTheme() {
    return root.dataset.theme || (darkQuery.matches ? "dark" : "light");
  }

  function syncTheme() {
    const theme = effectiveTheme();
    root.dataset.effectiveTheme = theme;
    const label = theme === "dark" ? "Use the light theme" : "Use the dark theme";
    themeButton.setAttribute("aria-label", label);
    themeButton.title = label;
  }

  themeButton.addEventListener("click", () => {
    const next = effectiveTheme() === "dark" ? "light" : "dark";
    root.dataset.theme = next;
    try {
      localStorage.setItem("hearty-theme", next);
    } catch (error) {
      // Storage may be unavailable (private windows); the theme still applies.
    }
    syncTheme();
  });
  darkQuery.addEventListener("change", syncTheme);
  syncTheme();

  if (!DATA) {
    $("#main").insertAdjacentHTML(
      "afterbegin",
      '<p class="notice">The rules failed to load (rules.js is missing).</p>'
    );
    return;
  }

  /* ---- Text ------------------------------------------------------------------------- */

  const escapeHtml = (text) =>
    String(text)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");

  // Only links within the page and to https sites are made.
  const safeHref = (href) => (/^(#|https:\/\/)/.test(href) ? href : "#");

  // Inline Markdown: `code`, [links](#id) and **bold**.
  function inline(text) {
    const pattern = /`([^`]+)`|\[((?:[^\]`]|`[^`]*`)+)\]\(([^)\s]+)\)|\*\*([^*]+)\*\*/g;
    let out = "";
    let last = 0;
    let match;
    while ((match = pattern.exec(text))) {
      out += escapeHtml(text.slice(last, match.index));
      if (match[1] !== undefined) {
        const short = match[1].length <= 24 ? ' class="nowrap"' : "";
        out += "<code" + short + ">" + escapeHtml(match[1]) + "</code>";
      } else if (match[2] !== undefined) {
        out += '<a href="' + escapeHtml(safeHref(match[3])) + '">' + inline(match[2]) + "</a>";
      } else {
        out += "<strong>" + inline(match[4]) + "</strong>";
      }
      last = pattern.lastIndex;
    }
    return out + escapeHtml(text.slice(last));
  }

  // Block Markdown: paragraphs separated by blank lines, and `- ` lists.
  function markdown(text) {
    if (!text) return "";
    return text
      .split(/\n\s*\n/)
      .map((block) => {
        const lines = block.split("\n");
        if (lines[0].startsWith("- ")) {
          const items = [];
          for (const line of lines) {
            if (line.startsWith("- ")) items.push(line.slice(2));
            else items[items.length - 1] += " " + line.trim();
          }
          return "<ul>" + items.map((item) => "<li>" + inline(item) + "</li>").join("") + "</ul>";
        }
        return "<p>" + inline(lines.join(" ")) + "</p>";
      })
      .join("");
  }

  // Plain text for searching: Markdown punctuation dropped, lower case.
  const searchable = (...parts) =>
    parts
      .flat()
      .filter(Boolean)
      .join(" ")
      .replace(/[`*]/g, "")
      .toLowerCase();

  /* ---- Code ------------------------------------------------------------------------- */

  const span = (kind, text) => '<span class="tok-' + kind + '">' + escapeHtml(text) + "</span>";

  // One line of Clausewitz script: comments, strings, operators, braces, and bare words,
  // which are keys before an operator or a brace, numbers, yes/no, or plain values.
  const SCRIPT_TOKEN = /(#.*)|("(?:[^"\\]|\\.)*"?)|(==|!=|<=|>=|\?=|=|<|>)|([{}])|(\s+)|([^\s{}=<>#"]+)/y;

  function highlightScript(line) {
    const tokens = [];
    SCRIPT_TOKEN.lastIndex = 0;
    let match;
    while (SCRIPT_TOKEN.lastIndex < line.length && (match = SCRIPT_TOKEN.exec(line))) {
      const kinds = ["com", "str", "op", "brace", "ws", "word"];
      const group = match.slice(1).findIndex((part) => part !== undefined);
      tokens.push([kinds[group], match[0]]);
    }
    return tokens
      .map(([kind, text], index) => {
        if (kind === "ws") return escapeHtml(text);
        if (kind !== "word") return span(kind, text);
        const next = tokens.slice(index + 1).find(([other]) => other !== "ws");
        if (next && (next[0] === "op" || next[1] === "{")) return span("key", text);
        if (/^-?\d+(\.\d+)?%?$/.test(text)) return span("num", text);
        if (/^(yes|no)$/i.test(text)) return span("kw", text);
        return escapeHtml(text);
      })
      .join("");
  }

  // One line of a localisation file: `key:0 "text"`, the `l_<language>:` header, comments.
  function highlightLocalisation(line) {
    let match = /^(\s*)(#.*)$/.exec(line);
    if (match) return escapeHtml(match[1]) + span("com", match[2]);
    match = /^(\s*)([^\s:#"]+)(:)(\d*)(\s*)("(?:[^"\\]|\\.)*"?)?(.*)$/.exec(line);
    if (!match) return escapeHtml(line);
    return (
      escapeHtml(match[1]) +
      span("key", match[2]) +
      span("op", match[3]) +
      (match[4] ? span("num", match[4]) : "") +
      escapeHtml(match[5]) +
      (match[6] ? span("str", match[6]) : "") +
      (match[7].trim().startsWith("#") ? span("com", match[7]) : escapeHtml(match[7]))
    );
  }

  const lines = (text) => {
    const all = text.split("\n");
    if (all[all.length - 1] === "") all.pop();
    return all;
  };

  // Which lines of `before` and `after` a line diff removes and adds (longest common
  // subsequence of lines).
  function diff(before, after) {
    const n = before.length;
    const m = after.length;
    const common = Array.from({ length: n + 1 }, () => new Uint16Array(m + 1));
    for (let i = n - 1; i >= 0; i--) {
      for (let j = m - 1; j >= 0; j--) {
        common[i][j] =
          before[i] === after[j]
            ? common[i + 1][j + 1] + 1
            : Math.max(common[i + 1][j], common[i][j + 1]);
      }
    }
    const removed = new Array(n).fill("");
    const added = new Array(m).fill("");
    let i = 0;
    let j = 0;
    while (i < n && j < m) {
      if (before[i] === after[j]) {
        i++;
        j++;
      } else if (common[i + 1][j] >= common[i][j + 1]) {
        removed[i++] = "del";
      } else {
        added[j++] = "add";
      }
    }
    while (i < n) removed[i++] = "del";
    while (j < m) added[j++] = "add";
    return [removed, added];
  }

  // `ruler`, if given, is the column to mark (see `--max-width`).
  function codeBlock(textLines, path, marks, ruler) {
    const highlight = /\.yml$/.test(path) ? highlightLocalisation : highlightScript;
    const body = textLines
      .map((line, index) => {
        const mark = marks && marks[index] ? " " + marks[index] : "";
        return '<span class="line' + mark + '">' + (highlight(line) || " ") + "</span>";
      })
      .join("");
    const style = ruler ? ' style="--ruler: ' + Number(ruler) + '"' : "";
    return '<pre class="code' + (ruler ? " ruler" : "") + '"' + style + ' tabindex="0"><code>' + body + "</code></pre>";
  }

  const displayWidth = (line) => line.replace(/\t/g, "    ").length;

  function pane(label, path, content) {
    return (
      '<div class="pane"><div class="pane-head">' +
      (label ? '<span class="pane-label">' + label + "</span>" : "") +
      '<span class="pane-path">' +
      escapeHtml(path) +
      "</span></div>" +
      content +
      "</div>"
    );
  }

  function terminal(command, output, title) {
    return (
      '<div class="terminal"><div class="terminal-head"><span></span><span></span><span></span><b>' +
      escapeHtml(title || "terminal") +
      '</b></div><pre tabindex="0"><span class="prompt">$ </span><span class="cmd">' +
      escapeHtml(command) +
      "</span>\n" +
      output +
      "</pre></div>"
    );
  }

  // Rules and options whose examples depend on the line width, which they mark.
  const WIDTH_EXAMPLES = new Set(["join_short_blocks", "reflow_comments", "max_width"]);

  // The line width `command` formats to.
  function maxWidth(command) {
    const match = /--max-width[ =](\d+)/.exec(command || "");
    if (match) return Number(match[1]);
    const option = DATA.options.find((other) => other.id === "max_width");
    return Number(option.default[0]);
  }

  // An example: the files before (and after, if the command writes them), then what
  // hearty printed. `id` is the rule's or option's.
  function renderExample(example, id) {
    const writes = Boolean(example.after_command);
    const ruler = WIDTH_EXAMPLES.has(id) ? maxWidth(example.after_command) : 0;
    const rulerNote = ruler ? '<span class="ruler-note">column ' + ruler + " marked</span>" : "";
    let wide = false;
    const panes = [];
    for (const file of example.files) {
      const before = lines(file.before);
      if (!writes) {
        panes.push(pane("", file.path, codeBlock(before, file.path)));
        wide = wide || before.some((line) => displayWidth(line) > 58);
        continue;
      }
      const after = lines(file.after);
      wide = wide || before.concat(after).some((line) => displayWidth(line) > 58);
      const afterLabel = "After <code>" + escapeHtml(example.after_command) + "</code>";
      if (file.after === file.before) {
        panes.push(pane("Before" + rulerNote, file.path, codeBlock(before, file.path, null, ruler)));
        panes.push(
          pane(afterLabel, file.path, '<p class="pane-note">Unchanged: hearty leaves this file as it is.</p>')
        );
      } else {
        const [removed, added] = diff(before, after);
        panes.push(pane("Before" + rulerNote, file.path, codeBlock(before, file.path, removed, ruler)));
        panes.push(pane(afterLabel + rulerNote, file.path, codeBlock(after, file.path, added, ruler)));
      }
    }
    return (
      '<figure class="example">' +
      (example.title ? '<figcaption class="example-title">' + inline(example.title) + "</figcaption>" : "") +
      '<div class="panes' +
      (wide ? " stacked" : "") +
      '">' +
      panes.join("") +
      "</div>" +
      terminal(example.command, example.output) +
      "</figure>"
    );
  }

  /* ---- Rules ------------------------------------------------------------------------ */

  const groups = new Map(DATA.groups.map((group) => [group.id, group]));
  const kinds = new Map(DATA.block_kinds.map((kind) => [kind.id, kind]));
  const rulesById = new Map(DATA.rules.map((rule) => [rule.id, rule]));
  const kindChip = (id) =>
    '<a class="kind-chip" href="#field_order_' + escapeHtml(id) + '">' + escapeHtml(kinds.get(id).name) + "</a>";

  function ruleCard(rule) {
    const card = document.createElement("details");
    card.className = "rule";
    card.id = rule.id;
    card.dataset.group = rule.group;
    card.innerHTML =
      '<summary><span class="rule-head"><span class="rule-title">' +
      inline(rule.title) +
      '</span><code class="rule-id">' +
      escapeHtml(rule.id) +
      '</code><a class="permalink" href="#' +
      escapeHtml(rule.id) +
      '" title="Link to this rule" aria-label="Link to ' +
      escapeHtml(rule.id) +
      '">#</a></span><span class="badges">' +
      (rule.fix ? '<span class="badge badge-fix" title="Fixed by hearty --fix">--fix</span>' : "") +
      '</span><span class="rule-summary">' +
      inline(rule.summary) +
      '</span></summary><div class="rule-body"></div>';
    card.addEventListener("toggle", () => {
      if (card.open) renderRuleBody(card);
    });
    return card;
  }

  function fieldOrders() {
    return (
      '<div class="kinds">' +
      DATA.block_kinds
        .map(
          (kind) =>
            '<details class="kind" id="field_order_' +
            escapeHtml(kind.id) +
            '"><summary><span class="kind-name">' +
            escapeHtml(kind.name) +
            '</span><span class="kind-count">' +
            kind.fields.length +
            " fields</span></summary>" +
            '<div class="kind-body"><p>' +
            inline(kind.location) +
            '</p><ol class="field-chips">' +
            kind.fields.map((field) => "<li><code>" + escapeHtml(field) + "</code></li>").join("") +
            "</ol>" +
            (kind.redundant_rules.length
              ? "<p>Redundant fields: " +
                kind.redundant_rules
                  .map((id) => '<a href="#' + escapeHtml(id) + '">' + inline(rulesById.get(id).title) + "</a>")
                  .join(", ") +
                ".</p>"
              : "") +
            "</div></details>"
        )
        .join("") +
      "</div>"
    );
  }

  function renderRuleBody(card) {
    if (card.dataset.rendered) return;
    card.dataset.rendered = "true";
    const rule = rulesById.get(card.id);
    const group = groups.get(rule.group);
    const facts = [];
    if (rule.applies_to.length) {
      facts.push(["Applies to", rule.applies_to.map(kindChip).join("")]);
    }
    if (rule.fix !== null) {
      facts.push([
        "Fixable",
        rule.fix ? 'Yes, by <a href="#--fix"><code>hearty --fix</code></a>' : "No",
      ]);
    }
    facts.push(["Group", '<a href="#group-' + escapeHtml(group.id) + '">' + escapeHtml(group.name) + "</a>"]);
    let html =
      '<dl class="facts">' +
      facts.map(([term, value]) => "<div><dt>" + term + ":</dt><dd>" + value + "</dd></div>").join("") +
      "</dl>";
    html += "<h4>What it does</h4>" + markdown(rule.what);
    if (rule.id === "field_order") html += fieldOrders();
    html += "<h4>Why</h4>" + markdown(rule.why);
    if (rule.notes) html += "<h4>Good to know</h4>" + markdown(rule.notes);
    html += "<h4>" + (rule.examples.length > 1 ? "Examples" : "Example") + "</h4>";
    html += rule.examples.map((example) => renderExample(example, rule.id)).join("");
    card.querySelector(".rule-body").innerHTML = html;
  }

  /* ---- Options ---------------------------------------------------------------------- */

  const optionId = (option) => (option.long ? "--" + option.long : option.id);

  function optionName(option) {
    if (option.positional) return "[" + option.value_names.join(" ") + "]";
    let name = (option.short ? "-" + option.short + ", " : "") + "--" + option.long;
    if (option.value_names.length) name += " <" + option.value_names.join(" ") + ">";
    return name;
  }

  const sentence = (text) => (/[.!?]$/.test(text) ? text : text + ".");

  function optionCard(option) {
    const card = document.createElement("article");
    card.className = "option";
    card.id = optionId(option);
    card.dataset.group = "options";
    const facts = [];
    if (option.default.length) {
      facts.push(["Default", option.default.map((value) => "<code>" + escapeHtml(value) + "</code>").join(" ")]);
    }
    if (option.possible_values.length) {
      facts.push([
        "Possible values",
        option.possible_values.map((value) => "<code>" + escapeHtml(value) + "</code>").join(" "),
      ]);
    }
    if (option.repeatable) facts.push(["Repeatable", "Yes"]);
    for (const variable of DATA.environment) {
      if (variable.option === option.id) {
        facts.push(["Environment", '<a href="#' + escapeHtml(variable.name) + '"><code>' + escapeHtml(variable.name) + "</code></a>"]);
      }
    }
    if (option.conflicts_with.length) {
      const others = DATA.options.filter((other) => option.conflicts_with.includes(other.id));
      facts.push([
        "Conflicts with",
        others.map((other) => '<a href="#' + escapeHtml(optionId(other)) + '"><code>' + escapeHtml(optionName(other)) + "</code></a>").join(" "),
      ]);
    }
    card.innerHTML =
      '<h3 class="option-head"><code>' +
      escapeHtml(optionName(option)) +
      '</code><a class="permalink" href="#' +
      escapeHtml(card.id) +
      '" title="Link to this option" aria-label="Link to ' +
      escapeHtml(card.id) +
      '">#</a></h3>' +
      "<p>" +
      escapeHtml(sentence(option.help || "")) +
      "</p>" +
      markdown(option.details) +
      (facts.length
        ? '<dl class="facts">' +
          facts.map(([term, value]) => "<div><dt>" + term + ":</dt><dd>" + value + "</dd></div>").join("") +
          "</dl>"
        : "") +
      option.examples.map((example) => renderExample(example, option.id)).join("");
    return card;
  }

  function environmentCard(variable) {
    const card = document.createElement("article");
    card.className = "option";
    card.id = variable.name;
    card.dataset.group = "options";
    const facts = [];
    if (variable.default) facts.push(["Default", "<code>" + escapeHtml(variable.default) + "</code>"]);
    const option = DATA.options.find((other) => other.id === variable.option);
    if (option) {
      facts.push(["Option", '<a href="#' + escapeHtml(optionId(option)) + '"><code>' + escapeHtml(optionName(option)) + "</code></a>"]);
    }
    card.innerHTML =
      '<h3 class="option-head"><code>' +
      escapeHtml(variable.name) +
      '</code><a class="permalink" href="#' +
      escapeHtml(variable.name) +
      '" title="Link to this variable" aria-label="Link to ' +
      escapeHtml(variable.name) +
      '">#</a></h3>' +
      markdown(variable.description) +
      (facts.length
        ? '<dl class="facts">' +
          facts.map(([term, value]) => "<div><dt>" + term + ":</dt><dd>" + value + "</dd></div>").join("") +
          "</dl>"
        : "");
    return card;
  }

  /* ---- Page ------------------------------------------------------------------------- */

  // Everything the filters and search act on: the element, its group and its text.
  const items = [];

  function renderGroups(category, container) {
    for (const group of DATA.groups.filter((group) => group.category === category)) {
      const rules = DATA.rules.filter((rule) => rule.group === group.id);
      const section = document.createElement("section");
      section.className = "group";
      section.id = "group-" + group.id;
      section.dataset.group = group.id;
      section.setAttribute("aria-labelledby", "group-title-" + group.id);
      section.innerHTML =
        '<h3 class="group-title" id="group-title-' +
        escapeHtml(group.id) +
        '"><span class="dot" aria-hidden="true"></span>' +
        escapeHtml(group.name) +
        ' <span class="section-count">' +
        rules.length +
        "</span></h3>" +
        (group.intro ? '<div class="group-intro">' + markdown(group.intro) + "</div>" : "");
      for (const rule of rules) {
        const card = ruleCard(rule);
        section.appendChild(card);
        items.push({
          element: card,
          group: rule.group,
          text: searchable(
            rule.id,
            rule.title,
            rule.summary,
            rule.what,
            rule.why,
            rule.notes,
            group.name,
            rule.applies_to.map((id) => kinds.get(id).name),
            rule.id === "field_order" ? DATA.block_kinds.map((kind) => [kind.name, kind.fields]) : []
          ),
        });
      }
      container.appendChild(section);
    }
  }

  function renderOptions() {
    const list = $("#option-list");
    for (const option of DATA.options) {
      const card = optionCard(option);
      list.appendChild(card);
      items.push({
        element: card,
        group: "options",
        text: searchable(optionName(option), option.id, option.help, option.details, option.possible_values),
      });
    }
    const environment = $("#environment-list");
    for (const variable of DATA.environment) {
      const card = environmentCard(variable);
      environment.appendChild(card);
      items.push({ element: card, group: "options", text: searchable(variable.name, variable.description) });
    }
    $("#usage-output").innerHTML = terminal("hearty --help", DATA.usage);
  }

  function renderOverview() {
    const overview = DATA.overview;
    $("#overview-run").innerHTML =
      terminal(overview.command, overview.output) +
      '<details class="overview-files"><summary>The mod it ran on</summary><div class="panes stacked">' +
      overview.files.map((file) => pane("", file.path, codeBlock(lines(file.before), file.path))).join("") +
      "</div></details>";
  }

  function renderStats() {
    const lints = DATA.rules.filter((rule) => groups.get(rule.group).category === "lint");
    const redundant = DATA.rules.filter((rule) => rule.group === "redundant");
    const formatting = DATA.rules.filter((rule) => groups.get(rule.group).category === "format");
    // The redundant-field rules are lints too: counted apart, so the counts add up to the
    // number of rules.
    const stats = [
      [lints.length - redundant.length, "lints", "localisation"],
      [redundant.length, "redundant-field rules", "redundant"],
      [formatting.length, "formatting rules", "sorting"],
      [DATA.block_kinds.length, "block kinds with a field order", "field_order"],
      [DATA.options.length, "options", "options"],
    ];
    $("#stats").innerHTML = stats
      .map(
        ([count, label, group]) =>
          '<li data-group="' + group + '"><span class="dot" aria-hidden="true"></span><b>' + count + "</b> " + label + "</li>"
      )
      .join("");
    $("#lints-count").textContent = lints.length;
    $("#formatting-count").textContent = formatting.length;
    $("#options-count").textContent = DATA.options.length;
    for (const element of document.querySelectorAll("[data-constant]")) {
      element.textContent = DATA.constants[element.dataset.constant];
    }
  }

  /* ---- Filters and search ----------------------------------------------------------- */

  const selected = new Set();
  const search = $("#search");
  const filters = $("#filters");
  const clearButton = $("#clear");
  const expandButton = $("#expand");

  function renderFilters() {
    const chip = (id, name, count) =>
      '<button class="chip" type="button" data-group="' +
      id +
      '" aria-pressed="false"><span class="dot" aria-hidden="true"></span>' +
      escapeHtml(name) +
      ' <span class="chip-count">' +
      count +
      "</span></button>";
    const byCategory = (category) =>
      DATA.groups
        .filter((group) => group.category === category)
        .map((group) => chip(group.id, group.name, DATA.rules.filter((rule) => rule.group === group.id).length))
        .join("");
    // Each category's chips stay on a line with its label: the row wraps between them.
    filters.innerHTML =
      '<span class="filter-group"><span class="filter-label">Lints</span>' +
      byCategory("lint") +
      '</span><span class="filter-group"><span class="filter-label">Formatting</span>' +
      byCategory("format") +
      '</span><span class="filter-group">' +
      chip("options", "Options & variables", DATA.options.length + DATA.environment.length) +
      "</span>";
    filters.addEventListener("click", (event) => {
      const button = event.target.closest(".chip");
      if (!button) return;
      const group = button.dataset.group;
      if (selected.has(group)) selected.delete(group);
      else selected.add(group);
      applyFilters();
    });
  }

  function applyFilters(updateUrl = true) {
    const terms = search.value.toLowerCase().split(/\s+/).filter(Boolean);
    const filtering = terms.length > 0 || selected.size > 0;
    let shown = 0;
    for (const item of items) {
      const visible =
        (selected.size === 0 || selected.has(item.group)) && terms.every((term) => item.text.includes(term));
      item.element.hidden = !visible;
      if (visible) shown++;
    }
    for (const group of document.querySelectorAll(".group")) {
      group.hidden = !group.querySelector(".rule:not([hidden])");
    }
    $("#lints").hidden = !$("#lints .rule:not([hidden])");
    $("#formatting").hidden = !$("#formatting .rule:not([hidden])");
    const anyOption = $("#options .option:not([hidden])");
    $("#options").hidden = !anyOption;
    $("#environment").hidden = !$("#environment-list .option:not([hidden])");
    $("#usage").hidden = filtering;
    $("#usage-output").hidden = filtering;
    $("#overview").hidden = filtering;
    for (const button of filters.querySelectorAll(".chip")) {
      button.setAttribute("aria-pressed", String(selected.has(button.dataset.group)));
    }
    clearButton.hidden = !filtering;
    $("#count").textContent = filtering
      ? shown + " of " + items.length + " shown"
      : DATA.rules.length + " rules, " + DATA.options.length + " options, " + DATA.environment.length + " variables";
    let empty = $("#empty");
    if (shown === 0) {
      if (!empty) {
        empty = document.createElement("p");
        empty.id = "empty";
        empty.className = "empty";
        $("#main").appendChild(empty);
      }
      empty.textContent = "Nothing matches" + (terms.length ? " “" + search.value.trim() + "”" : "") + ".";
    } else if (empty) {
      empty.remove();
    }
    if (updateUrl) {
      const params = new URLSearchParams();
      if (search.value.trim()) params.set("q", search.value.trim());
      if (selected.size) params.set("groups", [...selected].join(","));
      const query = params.toString();
      history.replaceState(null, "", (query ? "?" + query : location.pathname) + location.hash);
    }
  }

  function clearFilters() {
    search.value = "";
    selected.clear();
    applyFilters();
  }

  function readUrl() {
    const params = new URLSearchParams(location.search);
    search.value = params.get("q") || "";
    for (const group of (params.get("groups") || "").split(",")) {
      if (group === "options" || groups.has(group)) selected.add(group);
    }
  }

  /* ---- Navigation ------------------------------------------------------------------- */

  // Shows the element with id `id`: clears filters hiding it, opens the cards around it
  // (rendering them), scrolls to it and briefly highlights it.
  function reveal(id) {
    if (!id) return;
    let target = document.getElementById(id);
    if (!target && id.startsWith("field_order_") && rulesById.has("field_order")) {
      renderRuleBody(document.getElementById("field_order"));
      target = document.getElementById(id);
    }
    if (!target) return;
    if (target.closest("[hidden]")) clearFilters();
    for (let element = target; element; element = element.parentElement) {
      if (element.tagName === "DETAILS") {
        if (element.classList.contains("rule")) renderRuleBody(element);
        element.open = true;
      }
    }
    target.scrollIntoView({ block: "start" });
    const card = target.closest(".rule, .option, .kind");
    if (card) {
      card.classList.remove("flash");
      void card.offsetWidth;
      card.classList.add("flash");
      setTimeout(() => card.classList.remove("flash"), 1600);
      const focusable = card.querySelector("summary") || card;
      if (focusable === card) card.tabIndex = -1;
      focusable.focus({ preventScroll: true });
    }
  }

  const hashId = () => decodeURIComponent(location.hash.slice(1));

  // Links scroll their target to just below the sticky toolbar (see `scroll-padding-top`),
  // whose height changes as its chips wrap.
  const toolbar = $(".toolbar");
  const syncToolbarHeight = () => root.style.setProperty("--toolbar-height", toolbar.offsetHeight + "px");

  function setExpanded(open) {
    for (const card of document.querySelectorAll(".rule")) {
      if (card.hidden) continue;
      if (open) renderRuleBody(card);
      card.open = open;
    }
    expandButton.textContent = open ? "Collapse all" : "Expand all";
    expandButton.dataset.open = String(open);
  }

  /* ---- Start ------------------------------------------------------------------------ */

  renderStats();
  renderOverview();
  renderGroups("lint", $("#lint-groups"));
  renderGroups("format", $("#format-groups"));
  renderOptions();
  renderFilters();
  readUrl();
  applyFilters(false);

  search.addEventListener("input", () => applyFilters());
  search.addEventListener("keydown", (event) => {
    if (event.key === "Escape") {
      search.value = "";
      applyFilters();
    }
  });
  clearButton.addEventListener("click", clearFilters);
  expandButton.addEventListener("click", () => setExpanded(expandButton.dataset.open !== "true"));
  document.addEventListener("keydown", (event) => {
    const typing = /^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement.tagName);
    if (event.key === "/" && !typing && !event.ctrlKey && !event.metaKey && !event.altKey) {
      event.preventDefault();
      search.focus();
    }
  });
  syncToolbarHeight();
  if ("ResizeObserver" in window) new ResizeObserver(syncToolbarHeight).observe(toolbar);
  window.addEventListener("hashchange", () => reveal(hashId()));
  if (location.hash) reveal(hashId());
})();
